func TestTmpSanityAgainstImpl4(t *testing.T) {
	inputs := [][]string{
		{},
		{""},
		{"hello"},
		{"hello\n"},
		{"hello\nworld"},
		{"hello\nworld\n"},
		{"\n"},
		{"\n\n"},
		{"a b\n c\n\n d"},
		{"héllo wörld\n"},
		{"π = 3.14159\n"},
		{"日本語の文字\n"},
		{"tab\there\n"},
		{"line1", "line2", "line3\n"},
		{"\n", "abc"},
	}
	for _, in := range inputs {
		got := NewCounter()
		want := &Impl4{}
		for _, s := range in {
			got.AddString(s)
			want.AddString(s)
		}
		if got.Lines() != want.Lines() || got.Letters() != want.Letters() || got.Characters() != want.Characters() {
			t.Errorf("inputs %q: got (L=%d, Le=%d, C=%d), want (L=%d, Le=%d, C=%d)",
				in, got.Lines(), got.Letters(), got.Characters(),
				want.Lines(), want.Letters(), want.Characters())
		}
	}
}
